(7633303, 1237907, 24983, '<td valign="top">https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1237907#</td>', 'https://www.dpchallenge.com/challenge_vote_image.php?IMAGE_ID=1237907#', '2019-06-21 22:27:55.000000', NULL, 1),
(7633415, 1237875, 114285, '<td valign="top">Lovely minimalism.</td>', 'Lovely minimalism.', '2019-06-24 06:16:04.000000', NULL, 1),
(7633416, 1237903, 114285, '<td valign="top">Great lines!</td>', 'Great lines!', '2019-06-24 06:16:32.000000', NULL, 1),
(7633467, 1237873, 24454, '<td valign="top">Very interesting!  There''s something always artful about bicycles, and this is a cool way to create art for this challenge.</td>', 'Very interesting!  There''s something always artful about bicycles, and this is a cool way to create art for this challenge.', '2019-06-24 15:11:02.000000', NULL, 1),
(7633468, 1237670, 24454, '<td valign="top">It looks like a modern water color painting.  I like it!</td>', 'It looks like a modern water color painting.  I like it!', '2019-06-24 15:12:10.000000', NULL, 1),
(7633469, 1237919, 24454, '<td valign="top">I love this one.  It''s so common to see waterfalls and streams with the long slow shutter, but silky crashing waves in an ocean are so pretty and ethereal shot this way.  Especially in contrast to the edgy pier.</td>', 'I love this one.  It''s so common to see waterfalls and streams with the long slow shutter, but silky crashing waves in an ocean are so pretty and ethereal shot this way.  Especially in contrast to the edgy pier.', '2019-06-24 15:14:03.000000', NULL, 1),
(7633470, 1237802, 24454, '<td valign="top">I really love this.  The colorful light and the crisp starbursts in the urban setting:  I could frame it and hang it on my wall.</td>', 'I really love this.  The colorful light and the crisp starbursts in the urban setting:  I could frame it and hang it on my wall.', '2019-06-24 15:15:45.000000', NULL, 1),
(7633471, 1237783, 24454, '<td valign="top">What a gorgeous scene!  I am especially in love with the smooth, silky water</td>', 'What a gorgeous scene!  I am especially in love with the smooth, silky water', '2019-06-24 15:17:45.000000', NULL, 1),
(7633472, 1237922, 24454, '<td valign="top">Gasp!  I.  Love, love, LOVE this!  That silky water!!  The crisp horizon!  The edgy posts.  I''m only 32% into my voting, but so far... this one, it would be my 1st purchase if they were all for sale in a gallery!</td>', 'Gasp!  I.  Love, love, LOVE this!  That silky water!!  The crisp horizon!  The edgy posts.  I''m only 32% into my voting, but so far... this one, it would be my 1st purchase if they were all for sale in a gallery!', '2019-06-24 15:20:12.000000', NULL, 1),
(7633473, 1237921, 24454, '<td valign="top">So LUSCIOUS!  This has to be in the top few!</td>', 'So LUSCIOUS!  This has to be in the top few!', '2019-06-24 15:21:34.000000', NULL, 1),
(7633474, 1237924, 24454, '<td valign="top">This makes me smile.  I have been at several art show openings, and my brain has actually tried to create this scenario for me.  Only a few, but a few just had art that made it all blur together into nothingness.</td>', 'This makes me smile.  I have been at several art show openings, and my brain has actually tried to create this scenario for me.  Only a few, but a few just had art that made it all blur together into nothingness.', '2019-06-24 15:24:13.000000', NULL, 1),
(7633476, 1237875, 24454, '<td valign="top">This!  It''s REALLY a standout and I love it so much.  What a place.  What a moment.</td>', 'This!  It''s REALLY a standout and I love it so much.  What a place.  What a moment.', '2019-06-24 15:25:24.000000', NULL, 1),
(7633477, 1237901, 24454, '<td valign="top">Wow!  How wonderful!!!</td>', 'Wow!  How wonderful!!!', '2019-06-24 15:26:19.000000', NULL, 1),
(7633478, 1237700, 24454, '<td valign="top">I love this!  What artistry! I think this one better get added to my favorites!</td>', 'I love this!  What artistry! I think this one better get added to my favorites!', '2019-06-24 15:28:07.000000', NULL, 1),
(7633479, 1237903, 24454, '<td valign="top">This is crazy cool!!!  I love every single thing about this.  The motionless bikers in the bottom right corner add interest to the rest of the scene so fast in motion.</td>', 'This is crazy cool!!!  I love every single thing about this.  The motionless bikers in the bottom right corner add interest to the rest of the scene so fast in motion.', '2019-06-24 15:30:00.000000', NULL, 1),
