(7633537, 1237700, 10848, '<td valign="top">Such a mystical image. Love it 8</td>', 'Such a mystical image. Love it 8', '2019-06-24 21:20:18.000000', NULL, 1),
(7633604, 1237903, 115753, '<td valign="top">I like the overall image but the oversharpness seems to put a sense of unnaturalness to it. With more light trails and more contrast I think the effect would have been significantly stronger</td>', 'I like the overall image but the oversharpness seems to put a sense of unnaturalness to it. With more light trails and more contrast I think the effect would have been significantly stronger', '2019-06-25 23:53:12.000000', NULL, 1),
(7633605, 1237925, 115753, '<td valign="top">Lovely photo, the busyness of it all seems very well balanced in contrast with the upper half of the photo. Obviously you cant control the precise composition but I think this was pretty well done</td>', 'Lovely photo, the busyness of it all seems very well balanced in contrast with the upper half of the photo. Obviously you cant control the precise composition but I think this was pretty well done', '2019-06-25 23:54:50.000000', NULL, 1),
